"""Build a connection string for the loopback-only Docker PostgreSQL service."""

from pathlib import Path

from dotenv import dotenv_values
from psycopg.conninfo import make_conninfo


def local_conninfo(env_path: Path) -> str:
    settings = dotenv_values(env_path, interpolate=False)
    password = settings.get("POSTGRES_PASSWORD")
    if not password:
        raise RuntimeError(
            "Local PostgreSQL requires POSTGRES_PASSWORD in backend/.env.docker. "
            "Use the file generated by the local Docker setup."
        )
    port = settings.get("POSTGRES_PORT") or "55432"
    if not port.isascii() or not port.isdecimal() or len(port) > 5 or not 1 <= int(port) <= 65535:
        raise RuntimeError("POSTGRES_PORT in backend/.env.docker must be a valid TCP port.")
    return make_conninfo(
        host="127.0.0.1",
        hostaddr="127.0.0.1",
        port=port,
        dbname="retail_catalog",
        user="retail_local",
        password=password,
        sslmode="disable",
    )
